def skill():
    F = Fraction
    dA, dB = F(1, 5), F(4, 15)
    sA, sB = F(2, 15), F(6, 15)
    d, s = dA + dB, sA + sB
    v = (dA * s + sA * d) / (2 * d * s)
    return v.numerator + v.denominator

def standard():
    from itertools import product, combinations
    F = Fraction
    def one():
        out = []
        for die in range(1, 7):
            urn = ['w', 'w', 'b', 'b', 'b'] if die <= 2 else ['w', 'w', 'w', 'w', 'b']
            idx = list(combinations(range(5), 2))
            for i, j in idx:
                out.append((die <= 2, urn[i] != urn[j], F(1, 6 * len(idx))))
        return out
    O = one()
    den = num = F(0)
    for x, y in product(O, repeat=2):
        if x[1] != y[1]:
            p = x[2] * y[2]
            den += p
            if x[0]:
                num += p
    v = num / den
    return v.numerator + v.denominator

def unique():
    return [standard()]
